import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"回应与表情符号","description":"","frontmatter":{},"headers":[],"relativePath":"guide/misskey/reactions.md","filePath":"guide/misskey/reactions.md","lastUpdated":1789295632000}'),r={name:"guide/misskey/reactions.md"};function l(s,a,n,d,c,h){return i(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="回应与表情符号" tabindex="-1">回应与表情符号 <a class="header-anchor" href="#回应与表情符号" aria-label="Permalink to &quot;回应与表情符号&quot;">​</a></h1><h2 id="回应" tabindex="-1">回应 <a class="header-anchor" href="#回应" aria-label="Permalink to &quot;回应&quot;">​</a></h2><p>回应（Reaction）是 Misskey 特色互动方式：用任意 Emoji 表达态度，而不只是点赞。</p><ul><li>点击帖子下方的 <strong>+</strong> 打开回应选择器，选一个 Emoji 即可回应。</li><li>与点赞不同，回应可以表达喜怒哀乐（😂 😭 👍 ❤️ 等任意表情）。</li><li>点击帖子已有的回应可以查看回应者列表；再点一次自己发出的回应即可取消。</li><li>服务器管理员可以上传自定义表情，扩充可用的回应。</li></ul><h2 id="回应相关的隐私" tabindex="-1">回应相关的隐私 <a class="header-anchor" href="#回应相关的隐私" aria-label="Permalink to &quot;回应相关的隐私&quot;">​</a></h2><p>在「设置 → 隐私」中可以控制：</p><ul><li><strong>将回应设置为公开</strong>：开启后，你发表过的回应会公开可见。</li><li><strong>回应接受范围</strong>：可限制其他用户能在你的帖子上使用哪些回应（如仅允许图标类表情）。</li></ul><h2 id="表情面板" tabindex="-1">表情面板 <a class="header-anchor" href="#表情面板" aria-label="Permalink to &quot;表情面板&quot;">​</a></h2><p>发帖或回应时用到的 Emoji 来自表情面板：</p><ul><li>支持 Unicode Emoji 与服务器自定义表情（<code>:自定义表情:</code> 格式）。</li><li>在「设置 → 表情面板」可以整理常用表情、调整顺序。</li><li>发帖输入框上方的 MFM 功能菜单中也能快速插入表情。</li></ul><p>相关页面：<a href="/guide/posts">帖子与时间线</a>中的「互动」一节、<a href="/guide/misskey/mfm">MFM 语法</a>。</p>',11)])])}const p=e(r,[["render",l]]);export{m as __pageData,p as default};
